cd /tmp && python3 - <<'EOF'
import json, numpy as np, collections
for t in ['algebra','geometry','combinatorics','number_theory']:
    d=json.load(open(f'/tmp/dev_{t}.json'))
    qs=d['questions']
    print("="*20,t,len(qs))
    # per-variant sample accuracy, verifier AUC
    for v in range(5):
        cs=[s for q in qs for s in q['samples'] if s['variant']==v]
        acc=np.mean([s['correct'] for s in cs])
        pos=[s['score'] for s in cs if s['correct']]; neg=[s['score'] for s in cs if not s['correct']]
        auc=np.mean([p>n for p in pos for n in neg]) if pos and neg else float('nan')
        # within-variant wrong-answer clustering: for each q, max count of a single wrong answer among 4
        clus=[]
        for q in qs:
            ws=[s['answer'] for s in q['samples'] if s['variant']==v and not s['correct']]
            if ws: clus.append(max(collections.Counter(ws).values()))
        print(f" v{v} acc={acc:.2f} auc={auc:.2f} mean_pos={np.mean(pos) if pos else 0:.2f} mean_neg={np.mean(neg) if neg else 0:.2f} wrong_clus={np.mean(clus):.2f}")
    # cross-variant clustering: do wrong answers repeat across variants?
    cross=[]
    for q in qs:
        byv=collections.defaultdict(set)
        for s in q['samples']:
            if not s['correct']: byv[s['variant']].add(s['answer'])
        vs=list(byv)
        for i in range(len(vs)):
            for j in range(i+1,len(vs)):
                cross.append(len(byv[vs[i]]&byv[vs[j]])>0)
    print(" cross-variant wrong overlap rate", np.mean(cross) if cross else None)
